import { useCallback } from 'react'
import type { CSSProperties } from 'react'
import { useNavigate, useLocation } from 'react-router'
import { Box, Float, Skeleton } from '@chakra-ui/react'

import { useRefVideoAutoLoopPlay } from '~/ui/parts/VideoView'
import { MyYesButton } from '~/ui/parts/MyButton'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


export type MethodLinkOptionProp = {
  size?: 'base' | 'sm';
}

type MethodLinkProp = MethodLinkOptionProp & {
  title: string;
  thumbnailVideo?: string;
  thumbnailImage?: string;
  openDrawer: () => void;
}
export function MethodLink(prop: MethodLinkProp) {
  const { title, thumbnailVideo, thumbnailImage, openDrawer, size = 'base' } = prop;
  const { inViewRef, videoRefs } = useRefVideoAutoLoopPlay(1);
  
  return (
    <Box
      className='method-link'
      css={styles.outer} 
      onClick={openDrawer}
      style={{ '--width': size=='sm' ? '5em' : '10em' } as CSSProperties}
      >
      <MyYesButton as='span' h='fit-content' w='fit-content'>
        {title}
        <Box as='span' ref={inViewRef} css={styles.thumbnail}>
          <Skeleton as='span' />
          {thumbnailImage && <img src={thumbnailImage} loading='lazy' />}
          {thumbnailVideo && <video ref={videoRefs.current[0]} src={thumbnailVideo} playsInline muted />}
        </Box>
      </MyYesButton>
      {size=='base' && <ConductorWire />}
    </Box>
  )
}

export function useMethodLinkInDrawer(curKind: string) {
  const navigate = useNavigate();
  const location = useLocation();
  const methodName = location.hash?.substr(1) || '';
  
  const openDrawer = useCallback((kind: string, name: string) => {
    return () => {
      if (location.pathname.endsWith(`${kind}`)) {
        navigate(`${location.pathname}#${name}`);
      } else {
        navigate(`${location.pathname.replace(`${curKind}`, `${kind}`)}#${name}`);
      }
    }
  }, [location, methodName, navigate, curKind]);
  return openDrawer;
}









